const root = $input.first().json;

function collectNamedArrays(value, found = []) {
  if (!value || typeof value !== 'object') return found;
  if (Array.isArray(value.questions)) found.push(value.questions);
  if (Array.isArray(value.urlParameters)) found.push(value.urlParameters);
  if (Array.isArray(value.calculations)) found.push(value.calculations);
  if (Array.isArray(value)) {
    for (const item of value) collectNamedArrays(item, found);
  } else {
    for (const item of Object.values(value)) collectNamedArrays(item, found);
  }
  return found;
}

const fields = {};
for (const list of collectNamedArrays(root)) {
  for (const item of list) {
    if (!item || !item.name) continue;
    fields[String(item.name).trim().toLowerCase()] = item.value ?? '';
  }
}
if (Object.keys(fields).length === 0 && typeof root === 'object') {
  for (const [k, v] of Object.entries(root)) {
    fields[String(k).trim().toLowerCase()] = v;
  }
}

function pick(...keys) {
  for (const key of keys) {
    const kLow = key.toLowerCase();
    for (const [fk, fv] of Object.entries(fields)) {
      if (fk.includes(kLow) && fv) return String(fv).trim();
    }
  }
  return '';
}

const name = pick('full name', 'applicant name', 'name') || 'Guest Tenant';
const email = pick('email address', 'email') || 'support@homelyo.eu';
const phone = pick('phone', 'whatsapp') || '';
const rawRoom = pick('selected room', 'room preference', 'room') || 'KE1';
const roomMatch = rawRoom.match(/KE[1-4]/i);
const room = roomMatch ? roomMatch[0].toUpperCase() : 'KE1';

const startDate = pick('target move-in', 'move-in date', 'start date', 'start') || '2026-11-01';
const durationMonths = parseInt(pick('stay length', 'duration', 'months') || '6', 10);

const rentMap = { KE1: 629, KE2: 649, KE3: 619, KE4: 569 };
const depositMap = { KE1: 1258, KE2: 1298, KE3: 1238, KE4: 1138 };

return [{
  json: {
    name,
    email,
    phone,
    room,
    start_date: startDate,
    duration_months: durationMonths,
    rent_amount: rentMap[room] || 629,
    deposit_amount: depositMap[room] || 1258,
    source: 'Zite / Fillout Form gq1XFEqEWJus'
  }
}];

